<?php $type=$rows[0]['error_type'] ?? 'other';$catalog=lc_error_catalog();$statuses=['open'=>'待分析','investigating'=>'排查中','planned'=>'计划修复','resolved'=>'已处理','ignored'=>'已确认可忽略']; ?>
<div class="analysis-hero"><div><span class="eyebrow">ISSUE INVESTIGATION</span><h2><?= e($catalog[$type][0] ?? $type) ?></h2><p><?= e($catalog[$type][1] ?? '请结合设备版本和日志判断。') ?></p></div><a class="btn ghost" href="<?= e(lc_diag_url('/admin')) ?>">返回工作台</a></div>
<div class="analysis-kpis compact"><?php foreach([['事件条数',$summary['events']],['受影响设备',$summary['devices']],['软件版本',$summary['versions']]] as $k): ?><article class="metric-card"><span><?= e($k[0]) ?></span><strong><?= (int)$k[1] ?></strong></article><?php endforeach; ?></div>
<div class="analysis-grid"><section class="card"><h2>排查记录</h2><form method="post" action="/admin/issues/<?= e($fingerprint) ?>/update"><?= csrf_field() ?><input type="hidden" name="return_to" value="<?= e($_SERVER['REQUEST_URI']) ?>"><div class="field"><label for="issue-status">当前状态</label><select id="issue-status" name="status"><?php foreach($statuses as $key=>$label): ?><option value="<?= e($key) ?>" <?= $note['status']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="field"><label for="issue-note">复现步骤、判断与处理记录</label><textarea id="issue-note" name="note" rows="5" maxlength="2000" placeholder="记录客户操作、复现条件和后续处理…"><?= e($note['note']) ?></textarea></div><button class="btn">保存排查记录</button></form></section><section class="card"><h2>问题范围</h2><dl class="scope-list"><dt>首次记录</dt><dd><?= e($summary['first_at'] ?: '暂无') ?></dd><dt>最近记录</dt><dd><?= e($summary['latest'] ?: '暂无') ?></dd><dt>归类规则</dt><dd>平台、错误分类与归一化错误文本一致。不同错误仍需结合原始日志核实。</dd><dt>状态说明</dt><dd>将问题标记已处理不会删除日志，也不代表客户的软件已更新。</dd></dl></section></div>
<section class="card"><div class="section-title"><h2>最近 100 条相关记录</h2><span class="muted">优先查看不同设备和版本的样本</span></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>设备 / 版本</th><th>内容</th><th>原始日志</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= e($row['occurred_at']) ?></td><td><a href="/admin/userdata/<?= e(rawurlencode($row['identity'])) ?>"><?= e($row['identity']) ?></a><div>v<?= e($row['version'] ?: '未上报') ?></div></td><td class="event-message"><?= e($row['message']) ?><small><?= e(lc_source_name($row['source'])) ?></small></td><td><?php if($row['log_id']): ?><a class="btn ghost sm" href="/admin/logs/<?= (int)$row['log_id'] ?>?back=<?= e(rawurlencode($_SERVER['REQUEST_URI'])) ?>">查看日志</a><?php else: ?><span class="muted">结构化事件无日志附件</span><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="4" class="empty">当前时间范围没有相关事件。</td></tr><?php endif; ?></tbody></table></div></section>
